{"explanation":"In flat (Euclidean) geometry this follows from the parallel postulate. Draw a line through one vertex parallel to the opposite side: the two far angles reappear at that vertex as alternate interior angles, and together with the triangle's own angle there they exactly tile a straight line — 180°. Equivalently, the exterior angles of any convex polygon sum to 360°, so the interior angles of a triangle sum to 3×180° − 360° = 180°. Drag the vertices below: no matter how you deform the triangle, the three angles always fit together along the parallel line. (Fun fact: on curved surfaces this fails — spherical triangles have angle sums greater than 180°!)","manimCode":"function sectorVerts(cx, cy, r, a1, a2, steps) {
  let sweep = a2 - a1;
  while (sweep > Math.PI) sweep -= 2 * Math.PI;
  while (sweep < -Math.PI) sweep += 2 * Math.PI;
  const pts = [[cx, cy, 0]];
  for (let i = 0; i <= steps; i++) {
    const t = a1 + (sweep * i) / steps;
    pts.push([cx + r * Math.cos(t), cy + r * Math.sin(t), 0]);
  }
  return pts;
}

function bisectorPos(cx, cy, a1, a2, rad) {
  const x = Math.cos(a1) + Math.cos(a2);
  const y = Math.sin(a1) + Math.sin(a2);
  const m = Math.hypot(x, y) || 1;
  return [cx + (rad * x) / m, cy + (rad * y) / m, 0];
}

function angleDeg(a1, a2) {
  let d = Math.abs(a2 - a1) % (2 * Math.PI);
  if (d > Math.PI) d = 2 * Math.PI - d;
  return (d * 180) / Math.PI;
}

const title = new Text({ text: 'Why the angles of a triangle sum to 180°', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.5, 0]);

const hint = new Text({ text: 'A line through C parallel to AB: α and β reappear there (alternate interior angles) — all three tile a straight line!', color: GRAY, fontSize: 19 });
hint.moveTo([0, 3.1, 0]);

const dotA = new Dot({ point: [-2.6, -1.4, 0], color: YELLOW });
const dotB = new Dot({ point: [2.6, -1.4, 0], color: YELLOW });
const dotC = new Dot({ point: [1.0, 1.9, 0], color: YELLOW });

const tri = new Polygon({ vertices: [[-2.6, -1.4, 0], [2.6, -1.4, 0], [1.0, 1.9, 0]], color: WHITE });
tri.setFill(BLUE, 0.12);
tri.setStrokeWidth(3);

const parLine = new Polygon({ vertices: [[-0.4, 1.9, 0], [2.4, 1.9, 0]], color: GRAY });
parLine.setStrokeWidth(2);
parLine.setFillOpacity(0);

function makeArc(col) {
  const p = new Polygon({ vertices: [[0, 0, 0], [0.3, 0, 0], [0, 0.3, 0]], color: col });
  p.setFill(col, 0.5);
  p.setStrokeWidth(2);
  return p;
}
const arcA = makeArc(YELLOW);
const arcB = makeArc(TEAL);
const arcC = makeArc(RED);
const arcCa = makeArc(YELLOW);
const arcCb = makeArc(TEAL);

const labA = new Text({ text: 'α', color: YELLOW, fontSize: 26 });
const labB = new Text({ text: 'β', color: TEAL, fontSize: 26 });
const labC = new Text({ text: 'γ', color: RED, fontSize: 26 });
const labCa = new Text({ text: 'α', color: YELLOW, fontSize: 26 });
const labCb = new Text({ text: 'β', color: TEAL, fontSize: 26 });

let readout = new Text({ text: 'α + β + γ = 180°', color: WHITE, fontSize: 28 });
readout.moveTo([0, -3.35, 0]);

function updateAll() {
  const A = dotA.getCenter();
  const B = dotB.getCenter();
  const C = dotC.getCenter();
  tri.setVertices([A, B, C]);

  let dx = B[0] - A[0];
  let dy = B[1] - A[1];
  const m = Math.hypot(dx, dy) || 1;
  dx /= m;
  dy /= m;
  parLine.setVertices([
    [C[0] - 1.4 * dx, C[1] - 1.4 * dy, 0],
    [C[0] + 1.4 * dx, C[1] + 1.4 * dy, 0]
  ]);

  const aAB = Math.atan2(B[1] - A[1], B[0] - A[0]);
  const aAC = Math.atan2(C[1] - A[1], C[0] - A[0]);
  const aBA = Math.atan2(A[1] - B[1], A[0] - B[0]);
  const aBC = Math.atan2(C[1] - B[1], C[0] - B[0]);
  const aCA = Math.atan2(A[1] - C[1], A[0] - C[0]);
  const aCB = Math.atan2(B[1] - C[1], B[0] - C[0]);
  const aNeg = Math.atan2(-dy, -dx);
  const aPos = Math.atan2(dy, dx);

  const r = 0.45;
  arcA.setVertices(sectorVerts(A[0], A[1], r, aAB, aAC, 24));
  arcB.setVertices(sectorVerts(B[0], B[1], r, aBA, aBC, 24));
  arcC.setVertices(sectorVerts(C[0], C[1], r, aCA, aCB, 24));
  arcCa.setVertices(sectorVerts(C[0], C[1], r, aNeg, aCA, 24));
  arcCb.setVertices(sectorVerts(C[0], C[1], r, aCB, aPos, 24));

  const lr = 0.78;
  labA.moveTo(bisectorPos(A[0], A[1], aAB, aAC, lr));
  labB.moveTo(bisectorPos(B[0], B[1], aBA, aBC, lr));
  labC.moveTo(bisectorPos(C[0], C[1], aCA, aCB, lr));
  labCa.moveTo(bisectorPos(C[0], C[1], aNeg, aCA, lr));
  labCb.moveTo(bisectorPos(C[0], C[1], aCB, aPos, lr));

  const da = Math.round(angleDeg(aAB, aAC));
  const db = Math.round(angleDeg(aBA, aBC));
  const dc = Math.round(angleDeg(aCA, aCB));
  scene.remove(readout);
  readout = new Text({ text: 'α + β + γ = ' + da + '° + ' + db + '° + ' + dc + '° = 180°', color: WHITE, fontSize: 28 });
  readout.moveTo([0, -3.35, 0]);
  scene.add(readout);
}

await scene.play(new Write(title));
scene.add(hint);
scene.add(tri, parLine);
scene.add(arcA, arcB, arcC, arcCa, arcCb);
scene.add(dotA, dotB, dotC);
scene.add(labA, labB, labC, labCa, labCb);
scene.add(readout);
updateAll();

makeDraggable(dotA, scene, { constrainX: [-4.2, 4.2], constrainY: [-2.4, 2.2], onDrag: updateAll });
makeDraggable(dotB, scene, { constrainX: [-4.2, 4.2], constrainY: [-2.4, 2.2], onDrag: updateAll });
makeDraggable(dotC, scene, { constrainX: [-4.2, 4.2], constrainY: [-2.4, 2.2], onDrag: updateAll });

await scene.wait(999999);"}

